class VendingMachine:
    INITIAL_balance = None  # Not used directly, but for clarity

    def __init__(self):
        self._inventory = {}
        self._balance = 0

    @property
    def inventory(self):
        return self._inventory

    @inventory.setter
    def inventory(self, value):
        self._inventory = value

    @property
    def balance(self):
        return self._balance

    @balance.setter
    def balance(self, value):
        self._balance = value

    def add_item(self, item_name, price, quantity):
        if not self.restock_item(item_name, quantity):
            self.inventory[item_name] = {'price': price, 'quantity': quantity}

    def insert_coin(self, amount):
        self._balance += amount
        return self._balance

    def purchase_item(self, item_name):
        if not self._can_purchase(item_name):
            return False
        self._complete_purchase(item_name)
        return self._balance

    def _can_purchase(self, item_name):
        if item_name not in self.inventory:
            return False
        item = self.inventory[item_name]
        return item['quantity'] > 0 and self._balance >= item['price']

    def _complete_purchase(self, item_name):
        item = self.inventory[item_name]
        self._balance -= item['price']
        item['quantity'] -= 1

    def restock_item(self, item_name, quantity):
        if item_name in self.inventory:
            self.inventory[item_name]['quantity'] += quantity
            return True
        return False

    def display_items(self):
        if not self.inventory:
            return False
        return self._format_items(self.inventory)

    def _format_items(self, inventory):
        items = [
            f"{item_name} - ${item_info['price']} [{item_info['quantity']}]"
            for item_name, item_info in inventory.items()
        ]
        return "\n".join(items)
